export interface LibraryElement {
  id: string;
  name: string;
  category: string;
  kind: FeatureKind;
  /** Что обозначает и как применяется. */
  description: string;
  /** Пресет оформления для каждого стиля, где элемент есть. */
  variants: Partial<Record<StyleId, string>>;
  /** Знак меняет цвет по принадлежности (свои / противник / нейтральное). */
  sideAware?: boolean;
  /** Начертание не подтверждено первоисточниками — нужна сверка. */
  verify?: boolean;
  /** Синонимы для поиска. */
  keywords?: string[];
  /** Ссылки на первоисточники: «tm:XII-7», «ouo:6», «ver:3». */
  sources?: string[];
}

type Opts = { s?: boolean; v?: boolean; k?: string[]; src?: string[] };
const E = (
  id: string, name: string, category: string, kind: FeatureKind, description: string,
  variants: Partial<Record<StyleId, string>>, o: Opts = {},
): LibraryElement => ({
  id, name, category, kind, description, variants,
  ...(o.s ? { sideAware: true } : {}), ...(o.v ? { verify: true } : {}), ...(o.k ? { keywords: o.k } : {}), ...(o.src ? { sources: o.src } : {}),
});
const S = true;

